// Manifest stitches per-arch images into a multi-arch manifest list
// under the canonical tag. Sources are looked up at
// <repo>/<image>:<tag>-<arch> for each arch in the comma-separated
// arches list and combined into <repo>/<image>:<tag> via
// `docker buildx imagetools create`.
func (Package) Manifest(
	imageRepo string,
	imageName string,
	imageTag string,
	arches string,
) error {
	return util.PushMultiArchManifest(imageRepo, imageName, imageTag, arches)
}

// AllManifests stitches multi-arch manifest lists for every component
// in parallel, sourced from the installer's authoritative controller
// list so adding a new controller automatically extends coverage. Set
// PARALLEL_IMAGE_BUILD >= 1 to control worker concurrency (e.g.
// `PARALLEL_IMAGE_BUILD=4 mage package:allManifests ghcr.io/foo v1 amd64,arm64`).
func (Package) AllManifests(
	imageRepo string,
	imageTag string,
	arches string,
) error {
	// gather every component image emitted by the generator
	images := []string{
		"threeport-spring-boot-rest-api",
		"threeport-spring-boot-database-migrator",
		"threeport-spring-boot-springboot-controller",
	}

	tasks := make([]func() error, 0, len(images))
	for _, image := range images {
		image := image
		tasks = append(tasks, func() error {
			return util.PushMultiArchManifest(imageRepo, image, imageTag, arches)
		})
	}

	return util.RunParallel(parallelFromEnv(), tasks)
}

// parallelFromEnv returns the PARALLEL_IMAGE_BUILD env var as an int, defaulting to 1.
func parallelFromEnv() int {
	v := os.Getenv("PARALLEL_IMAGE_BUILD")
	if v == "" {
		return 1
	}
	n, err := strconv.Atoi(v)
	if err != nil || n < 1 {
		return 1
	}
	return n
}

// LoadImage builds and loads an image to the provided kind cluster.
func (Dev) LoadImage(kindClusterName string, component string) error {
	workingDir, arch, err := getBuildVals()
	if err != nil {
		return fmt.Errorf("failed to get build values: %w", err)
	}

	if err := util.BuildBinaries(
		workingDir,
		[]string{arch},
		[]string{fmt.Sprintf("cmd/%s", component)},
		false,
	); err != nil {
		return fmt.Errorf("failed to build binary: %w", err)
	}

	imageName := fmt.Sprintf("threeport-%s-%s", "spring-boot", component)

	dockerfileTarget := "release"

	if err := util.BuildImage(
		workingDir,
		"Dockerfile",
		dockerfileTarget,
		arch,
		component,
		"bin",
		nil,
		installer.DevImageNamespace,
		imageName,
		version.GetVersion(),
		false,
		true,
		kindClusterName,
	); err != nil {
		return fmt.Errorf("failed to build and load image: %w", err)
	}

	return nil
}

// Plugin compiles the extension's tptctl plugin.
func (Build) Plugin() error {
	buildCmd := exec.Command(
		"go",
		"build",
		"-o",
		"bin/spring-boot",
		"cmd/spring_boot/main_gen.go",
	)

	output, err := buildCmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("build failed for tptctl plugin with output '%s': %w", output, err)
	}

	fmt.Println("tptctl plugin built and available at bin/spring-boot")

	return nil
}

// Plugin builds the tptctl plugin and installs it in the tptctl plugin directory.
func (Install) Plugin() error {
	build := Build{}
	if err := build.Plugin(); err != nil {
		return fmt.Errorf("failed to build tptctl plugin: %w", err)
	}

	pluginDir := os.Getenv("THREEPORT_PLUGIN_DIR")
	if pluginDir == "" {
		dir, err := cli.DefaultPluginDir()
		if err != nil {
			return fmt.Errorf("failed to determine tptctl plugin directory: %w", err)
		}
		pluginDir = dir
	}
	if err := os.MkdirAll(pluginDir, 0o755); err != nil {
		return fmt.Errorf("failed to create tptctl plugin directory: %w", err)
	}

	outputPath := filepath.Join(pluginDir, "spring-boot")
	installCmd := exec.Command(
		"cp",
		"bin/spring-boot",
		outputPath,
	)

	output, err := installCmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("install failed for tptctl plugin with output '%s': %w", output, err)
	}

	fmt.Printf("tptctl plugin installed and available at %s\n", outputPath)

	return nil
}

// GenerateSwaggerDocs generates the API server swagger documentation served by the API.
func (Dev) GenerateSwaggerDocs() error {
	docsDestination := "pkg/api-server/v0/docs"
	swagCmd := exec.Command(
		"swag",
		"init",
		"--dir",
		"cmd/rest-api,pkg/api,pkg/api-server/v0",
		"--parseDependency",
		"--generalInfo",
		"main_gen.go",
		"--output",
		docsDestination,
	)

	output, err := swagCmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("API docs generation failed with output '%s': %w", output, err)
	}

	fmt.Printf("API docs generated in %s\n", docsDestination)

	return nil
}

// LocalRegistryUp starts a docker container to serve as a local container registry.
func (Dev) LocalRegistryUp() error {
	if err := tptdev.CreateLocalRegistry(); err != nil {
		return fmt.Errorf("failed to create local container registry: %w", err)
	}

	return nil
}

// LocalRegistryDown stops and removes the local container registry.
func (Dev) LocalRegistryDown() error {
	if err := tptdev.DeleteLocalRegistry(); err != nil {
		return fmt.Errorf("failed to remove local container registry: %w", err)
	}

	return nil
}

// getBuildVals returns the working directory and arch for builds.
func getBuildVals() (string, string, error) {
	workingDir, err := os.Getwd()
	if err != nil {
		return "", "", fmt.Errorf("failed to get working directory: %w", err)
	}

	arch := runtime.GOARCH

	return workingDir, arch, nil
}
